-- Step 3: Verify results
SELECT p.program_name, p.num_core_courses,
       COUNT(DISTINCT pcc.id) as total_core_rows,
       COUNT(DISTINCT CASE WHEN pcc.or_group_id > 0 THEN pcc.or_group_id END) as or_groups
FROM programs p
LEFT JOIN program_core_courses pcc ON pcc.program_id = p.id
GROUP BY p.id, p.program_name, p.num_core_courses
ORDER BY p.program_name;